// ---- RtcPeerConnection ----

/** The codes the calls of "rtcPeerConnection" reject with. */
export type RtcPeerConnectionCode = "failed" | "closed" | "notFound"

/** What a call throws to reject with a code of the contract — the app's promise rejects with it
 *  as the message. Any other error is a message the contract has no code for. */
export class RtcPeerConnectionError extends Error {
  constructor(readonly code: RtcPeerConnectionCode) { super(code) }
}

/** The events of "rtcPeerConnection": what the half sends the app. */
export interface RtcPeerConnectionEvents {
  negotiationNeeded(): void
  /** A local candidate for the other side; null = the gathering of this round is complete. */
  iceCandidate(payload: { candidate: IceCandidate | null }): void
  signalingStateChange(payload: { state: SignalingState }): void
  iceGatheringStateChange(payload: { state: IceGatheringState }): void
  iceConnectionStateChange(payload: { state: IceConnectionState }): void
  connectionStateChange(payload: { state: PeerConnectionState }): void
  /** A remote track arrived: the receiver's track of `transceiverId`, in the streams the other
   *  side put it in. */
  track(payload: { track: TrackInfo, streamIds: string[], transceiverId: string }): void
  /** A received track went mute (nothing arrives) or came back. */
  trackMute(payload: { trackId: string, muted: boolean }): void
  /** A received track ended: the other side removed it, or the connection closed. */
  trackEnded(payload: { trackId: string }): void
  /** The other side opened a data channel. */
  dataChannel(payload: DataChannelInfo): void
  dataChannelStateChange(payload: { id: string, state: DataChannelState }): void
  /** One message: `text` for a string, `binary` for bytes — exactly one of the two. */
  dataChannelMessage(payload: { id: string, text?: string, binary?: Uint8Array }): void
  dataChannelError(payload: { id: string, message: string }): void
  /** The buffered amount fell to the threshold or under it. */
  dataChannelBufferedAmountLow(payload: { id: string }): void
}

/** One RTCPeerConnection: a session, created with its configuration, closed by the SDK's close().
 *
 *  What the half implements. A call returns its result, or a promise of it; it rejects by throwing. */
export interface RtcPeerConnectionPlugin {
  /** Rejects with "failed" / "closed". */
  createOffer(options?: OfferOptions): SessionDescription | Promise<SessionDescription>
  /** Rejects with "failed" / "closed". */
  createAnswer(): SessionDescription | Promise<SessionDescription>
  /** Without a description: the implicit form — an answer when a remote offer is pending, an
   *  offer otherwise. Resolves with the description now in force (the one to signal).
   *  Rejects with "failed" / "closed". */
  setLocalDescription(description?: SessionDescription): SessionDescription | Promise<SessionDescription>
  /** Rejects with "failed" / "closed". */
  setRemoteDescription(description: SessionDescription): void | Promise<void>
  /** Without a candidate: the end of the remote candidates.
   *  Rejects with "failed" / "closed". */
  addIceCandidate(candidate?: IceCandidate): void | Promise<void>
  /** The next offer carries new ICE credentials. */
  restartIce(): void | Promise<void>
  /** Rejects with "failed". */
  setConfiguration(configuration: RtcConfiguration): void | Promise<void>
  /** Send a local track, in the streams named (one is made up when none is).
   *  Rejects with "notFound" / "failed" / "closed". */
  addTrack(trackId: string, streamIds?: string[]): SenderInfo | Promise<SenderInfo>
  /** Rejects with "notFound" / "closed". */
  removeTrack(senderId: string): void | Promise<void>
  /** Swap what a sender sends without renegotiating; null = send nothing.
   *  Rejects with "notFound" / "failed" / "closed". */
  replaceTrack(senderId: string, trackId: string | null): void | Promise<void>
  /** Rejects with "notFound". */
  getSenderParameters(senderId: string): SenderParameters | Promise<SenderParameters>
  /** The encodings' active / bitrate / scale; the layers themselves are set at addTransceiver.
   *  Rejects with "notFound" / "failed". */
  setSenderParameters(senderId: string, parameters: SenderParameters): void | Promise<void>
  /** Rejects with "notFound" / "failed" / "closed". */
  addTransceiver(kind: MediaKind, options?: TransceiverInit): TransceiverInfo | Promise<TransceiverInfo>
  getTransceivers(): TransceiverInfo[] | Promise<TransceiverInfo[]>
  /** Rejects with "notFound" / "failed". */
  setTransceiverDirection(transceiverId: string, direction: TransceiverDirection): void | Promise<void>
  /** Rejects with "notFound". */
  stopTransceiver(transceiverId: string): void | Promise<void>
  /** The RTCStatsReport as an object: the stats id → the stats object (`type`, `timestamp` in ms,
   *  the fields of its type). For one track's senders / receivers when `trackId` is given. */
  getStats(trackId?: string): Json | Promise<Json>
  /** Rejects with "failed" / "closed". */
  createDataChannel(label: string, options?: DataChannelInit): DataChannelInfo | Promise<DataChannelInfo>
  /** Rejects with "notFound" / "closed". */
  sendText(channelId: string, text: string): void | Promise<void>
  /** Rejects with "notFound" / "closed". */
  sendBinary(channelId: string, data: Uint8Array): void | Promise<void>
  /** Bytes queued and not yet sent.
   *  Rejects with "notFound". */
  getBufferedAmount(channelId: string): number | Promise<number>
  /** Rejects with "notFound". */
  setBufferedAmountLowThreshold(channelId: string, threshold: number): void | Promise<void>
  /** A no-op for an unknown id. */
  closeDataChannel(channelId: string): void | Promise<void>
  /** The session closed (the app's close, the world's teardown): stop what it started. */
  close?(): void
}

